code.late_row_check_whr.py:
"""[Whole-row variant, review D1 F-09: identical to scratchpad/hp-clo/late_row_check.py except that the recompute
uses monitor_wholerow.py.] Per-trial late-row test for an E-C/E-D aggregate (same test as used for E-C auth
and E-PS). For every trial whose second-segment the aggregator flagged, recompute
that segment from the verifier's OWN saved recorder snapshot and the saved anchor
chain with the shipped monitor (scheme from HOMEPROV_SCHEME), and classify:
delta_n > 0 -> rows arrived after the seal (not attributable to the arm);
delta_n <= 0 or segment vanished -> attributable. Read-only; writes one new file.
Usage: late_row_check.py TAG SNAPSHOT_DB CHAIN_JSONL
"""
import collections, importlib.util, json, os, sys

TAG, DB, CHAIN = sys.argv[1:4]
OUT = "<artifact-root>/exp/out"
dst = os.path.join(OUT, "%s_late_row_check.json" % TAG)
if os.path.exists(dst):
    raise SystemExit("refusing to overwrite " + dst)
os.environ.setdefault("HOMEPROV_SCRATCH", os.path.dirname(DB))
sys.path.insert(0, "<artifact-root>/monitor")
import monitor_wholerow as _wr  # whole-row baseline (review D1, F-09): same test, whole-row recompute
m = _wr.M
agg = json.load(open(os.path.join(OUT, "%s_other_principal_real.json" % TAG)))
first = {}
for line in open(CHAIN):
    if line.strip():
        rec = json.loads(line); p = rec.get("payload") or {}
        for g, segs in (p.get("sealed") or {}).items():
            if isinstance(segs, dict):
                for s, v in segs.items():
                    first.setdefault((g, str(s)), v)
phi = m.commit(m.load(DB))
per_arm = collections.defaultdict(lambda: {"n_valid": 0, "flagged": 0, "late_row": 0, "attributable": 0, "late_detail": []})
for t in agg["trials"]:
    if t.get("err") or t.get("error"):
        continue
    a = per_arm[t["arm"]]; a["n_valid"] += 1
    det = (t.get("_detection") or {}).get("second") or {}
    if not det.get("violation"):
        continue
    a["flagged"] += 1
    seg = det["segment"]; an = first.get(("second", seg)); rc = (phi.get("second") or {}).get(seg)
    dn = None if (an is None or rc is None) else rc["n"] - an["n"]
    if dn is not None and dn > 0:
        a["late_row"] += 1
        a["late_detail"].append({"room": t.get("room"), "trial": t.get("trial"), "segment": seg, "delta_n": dn})
    else:
        a["attributable"] += 1
res = {"tag": TAG, "scheme": m.SCHEME, "snapshot": DB, "chain": CHAIN, "per_arm": per_arm,
       "rule": "delta_n > 0: rows arrived after seal, not attributable; otherwise attributable",
       "how": __doc__}
json.dump(res, open(dst, "w"), indent=1, default=dict)
print(json.dumps({k: {kk: v[kk] for kk in ("n_valid", "flagged", "late_row", "attributable")} for k, v in per_arm.items()}),
      json.dumps({k: v["late_detail"] for k, v in per_arm.items() if v["late_detail"]}))

code.whr_preimage.py:
"""Pre-image test for the whole-row benign floor (review D1, F-09). Read-only. For every untouched one-second
segment that fails whole-row recomputation in one run, try to reproduce its FIRST ANCHORED whole-row root
from the final snapshot by restoring last_reported_ts to NULL (its value when the recorder inserts a state that
has not been reported again) on any subset of the segment's state rows that now carry a non-null value. A match
shows the failure is an in-place update of last_reported_ts after sealing. Writes exp/out/<TAG>_floor_preimage.json.
Usage: whr_preimage.py TAG DETECTION_JSON SNAPSHOT CHAIN"""
import itertools, json, os, sys
TAG, DET, DB, CHAIN = sys.argv[1:5]
OUT = "<artifact-root>/exp/out"
dst = os.path.join(OUT, f"{TAG}_floor_preimage.json")
if os.path.exists(dst):
    raise SystemExit("refusing to overwrite " + dst)
os.environ["HOMEPROV_SCRATCH"] = os.path.dirname(DB)
sys.path.insert(0, "<artifact-root>/monitor")
import monitor_wholerow as WR
M = WR.M
d = json.load(open(DET))
win = d.get("window") or {}
t0, t1 = win["t_start"], win["t_end"]
touched = {str((t.get("_detection") or {}).get("second", {}).get("segment")) for t in d["trials"]}
first = {}
for line in open(CHAIN):
    if line.strip():
        p = json.loads(line).get("payload") or {}
        for s, v in ((p.get("sealed") or {}).get("second") or {}).items():
            first.setdefault(s, v)
nodes = WR.load(DB)
by_seg = {}
for n in nodes:
    by_seg.setdefault(str(int(n[0] // 1)), []).append(n)


def root(ns):
    acc = M.ZERO
    for n in ns:
        acc = M.H(acc + WR.node_hash_wholerow(n))
    return acc.hex(), len(ns)


def with_lr_null(n):
    row = json.loads(n[9])
    row["row"]["last_reported_ts"] = None
    return n[:9] + (M._canon(row),)


res = {"untouched_failing": 0, "explained_by_last_reported_null": 0, "count_changed": 0, "unexplained": []}
for s, v in sorted(first.items()):
    if not (t0 - 1 <= int(s) <= t1 + 1) or s in touched:
        continue
    ns = by_seg.get(s, [])
    acc, cnt = root(ns)
    if acc == v["acc"] and cnt == v["n"]:
        continue
    res["untouched_failing"] += 1
    if cnt != v["n"]:
        res["count_changed"] += 1
        continue
    cand = [i for i, n in enumerate(ns) if n[1].startswith("s:") and json.loads(n[9])["row"].get("last_reported_ts") is not None]
    hit = False
    for k in range(1, min(len(cand), 6) + 1):
        for sub in itertools.combinations(cand, k):
            trial = [with_lr_null(n) if i in sub else n for i, n in enumerate(ns)]
            if root(trial)[0] == v["acc"]:
                hit = True; break
        if hit:
            break
    if hit:
        res["explained_by_last_reported_null"] += 1
    else:
        res["unexplained"].append({"segment": s, "rows": len(ns), "state_rows_with_last_reported": len(cand)})
res.update({"tag": TAG, "how": __doc__})
json.dump(res, open(dst, "w"), indent=1)
print(TAG, {k: (v if k != "unexplained" else len(v)) for k, v in res.items() if k != "how"}, res["unexplained"][:4])
